const $=id=>document.getElementById(id);let challenge=null,phone='',until=0,enabled=false;
async function call(path,data){const response=await fetch(path,{method:data?'POST':'GET',credentials:'same-origin',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});let result;try{result=await response.json();}catch{throw Error('Could not reach GoRide. Check your connection and try again.');}if(!response.ok)throw Error(result.error||'Sign-in could not be completed.');return result;}
function cooldown(){const seconds=Math.max(0,Math.ceil((until-Date.now())/1000));$('resend-code').disabled=seconds>0||!enabled;$('resend-code').textContent=seconds?'Resend in '+seconds+'s':'Resend code';$('send-code').disabled=!enabled||seconds>0;}
async function send(){if(!enabled)return;$('login-error').textContent='';$('send-code').disabled=true;$('resend-code').disabled=true;try{const data=await call('/api/customer-auth/start',{phone,consent:$('otp-consent').checked});challenge=data.challengeId;until=Date.now()+data.retryAfter*1000;$('phone-form').hidden=true;$('code-form').hidden=false;$('login-heading').textContent='Check your messages';$('login-info').textContent='Enter the code sent to '+data.maskedPhone+'. It expires after 10 minutes.';$('login-code').value='';$('login-code').focus();}catch(e){$('login-error').textContent=e.message;until=Date.now()+60000;}finally{cooldown();}}
$('phone-form').onsubmit=async e=>{e.preventDefault();phone=$('phone-number').value.trim();await send();};
$('resend-code').onclick=send;
$('change-number').onclick=()=>{challenge=null;$('phone-form').hidden=false;$('code-form').hidden=true;$('login-heading').textContent='Sign in with your phone';$('login-info').textContent='Enter your Indian mobile number. We’ll send a six-digit sign-in code by SMS.';$('login-error').textContent='';};
$('code-form').onsubmit=async e=>{e.preventDefault();$('verify-code').disabled=true;$('login-error').textContent='';try{await call('/api/customer-auth/check',{challengeId:challenge,code:$('login-code').value.trim()});location.replace('/account');}catch(e){$('login-error').textContent=e.message;}finally{$('verify-code').disabled=false;}};
(async()=>{try{const config=await call('/api/customer-auth/config');enabled=config.smsEnabled;$('login-service').textContent=enabled?'SMS sign-in is available.':'SMS sign-in is being set up. No codes can be sent yet.';$('private-preview').hidden=!config.privatePreview;cooldown();}catch(e){$('login-service').textContent='Sign-in is temporarily unavailable.';$('login-error').textContent=e.message;}})();setInterval(cooldown,1000);
